  s.info=[this](B::Monstey_Image m,const B::Monstey_Info&q){Hit(2,q.site,{q.output,48,0,0});for(U k=0;k<48;++k)m.Write(q.output+k,0x5A,1,q.site.pc);m.Write(q.output+4,page,4,q.site.pc);m.Write(q.output+0x28,granularity,4,q.site.pc);if(info_effect)info_effect(m);};
  s.sleep=[this](B::Monstey_Image m,const B::Monstey_Sleep&q){Hit(3,q.site,{q.milliseconds,q.alertable,0,0});m.Write(G().state,1,4,q.site.pc);if(sleep_effect)sleep_effect(m);};
  s.random=[this](B::Monstey_Image m,const B::Monstey_Site&q)->W{Hit(4,q,{0,0,0,0});if(random_effect)random_effect(m);return random_bits;};
  s.initialize=[this](B::Monstey_Image m,const B::Monstey_Cs&q)->U{Hit(5,q.site,{q.lock,q.spin,0,0});m.Write(q.lock,0xC5C5C5C5C5C5C5C5,8,q.site.pc);if(cs_effect)cs_effect(m);return Monstey_CsD;};
